'use strict';
// Audio is kept in memory and sent only after the user stops the recording.
window.JhonemeVoice=(()=>{
 let active=null;
 const mic='<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0014 0v-2M12 19v3M8 22h8"/></svg>';
 function mount(form){form.querySelectorAll('textarea[data-voice]').forEach(field=>{if(field.dataset.voiceMounted)return;field.dataset.voiceMounted='true';const box=document.createElement('div');box.className='voice-input';box.innerHTML=`<button type="button" class="btn small voice-start">${mic} Gravar pelo microfone</button><button type="button" class="btn small voice-cancel" hidden>Cancelar áudio</button><span class="voice-status" role="status" aria-live="polite">Até 2 min · você revisa antes de usar.</span><div class="voice-review" hidden><label>Revise a transcrição<textarea maxlength="10000" rows="5"></textarea></label><div class="actions"><button type="button" class="btn primary voice-apply">Usar este texto</button><button type="button" class="btn voice-discard">Descartar</button></div></div>`;(field.closest('label')||field).insertAdjacentElement('afterend',box);const start=box.querySelector('.voice-start'),status=box.querySelector('.voice-status'),review=box.querySelector('.voice-review'),draft=review.querySelector('textarea');
 const session={field,form,box,start,status,review,draft,recorder:null,stream:null,chunks:[],cancelled:false,controller:null,timer:null,clock:null};
 box.querySelector('.voice-cancel').addEventListener('click',()=>{cancel(session);status.textContent='Gravação cancelada.'});
 start.addEventListener('click',()=>session.recorder?.state==='recording'?stop(session):record(session));
 box.querySelector('.voice-discard').addEventListener('click',()=>{draft.value='';review.hidden=true;status.textContent='Transcrição descartada. Seu texto anterior foi mantido.'});
 box.querySelector('.voice-apply').addEventListener('click',()=>{const extra=draft.value.trim();if(!extra)return;const next=field.value.trim()?field.value.trim()+'\n\n'+extra:extra;if(field.maxLength>0&&next.length>field.maxLength){status.textContent='O texto ultrapassa o limite do campo. Encurte a transcrição antes de usar.';return}field.value=next;field.dispatchEvent(new Event('input',{bubbles:true}));review.hidden=true;draft.value='';field.focus();status.textContent='Texto acrescentado. Você ainda pode editar antes de salvar.'});
 const dialog=form.closest('dialog');dialog?.addEventListener('close',()=>cancel(session));form.addEventListener('submit',e=>{if(active===session){e.preventDefault();e.stopImmediatePropagation();status.textContent='Conclua ou cancele a gravação antes de salvar.'}else if(!review.hidden){e.preventDefault();e.stopImmediatePropagation();status.textContent='Use ou descarte a transcrição antes de salvar.'}},true);
 });}
 function release(s){clearTimeout(s.timer);clearInterval(s.clock);s.stream?.getTracks().forEach(t=>t.stop());s.stream=null;s.recorder=null;if(active===s)active=null;s.box.querySelector('.voice-cancel').hidden=true;s.start.disabled=false;s.start.innerHTML=mic+' Gravar pelo microfone'}
 function cancel(s=active){if(!s)return;s.cancelled=true;s.controller?.abort();if(s.recorder?.state==='recording')s.recorder.stop();release(s);s.chunks=[]}
 function stop(s){if(s.recorder?.state!=='recording')return;s.start.disabled=true;s.status.textContent='Transcrevendo com Deepgram…';s.recorder.stop()}
 async function record(s){
  if(active){s.status.textContent='Conclua a outra gravação antes de começar esta.';return}
  if(!window.JHONEME_SERVER){s.status.textContent='Gravação disponível na instalação da VPS com Deepgram. Nesta prévia, você pode escrever ou colar o briefing.';return}
  if(!window.isSecureContext||!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){s.status.textContent='Use um navegador com microfone em HTTPS ou localhost. Você também pode digitar.';return}
  if(!s.review.hidden){s.status.textContent='Use ou descarte a transcrição anterior antes de gravar outra.';return}
  active=s;s.cancelled=false;s.box.querySelector('.voice-cancel').hidden=false;s.start.disabled=true;s.status.textContent='Preparando o microfone…';
  try{const config=await fetch('/api/voice-config');if(!config.ok)throw Error(config.status===401?'Entre novamente na agência.':'Não foi possível consultar a transcrição.');if(!(await config.json()).available)throw Error('O Deepgram ainda precisa ser configurado no servidor.');if(s.cancelled)return;
   const stream=await navigator.mediaDevices.getUserMedia({audio:true});if(s.cancelled){stream.getTracks().forEach(t=>t.stop());return}s.stream=stream;
   const type=['audio/webm;codecs=opus','audio/webm','audio/mp4','audio/ogg;codecs=opus'].find(x=>MediaRecorder.isTypeSupported(x));if(!type)throw Error('Este navegador não oferece um formato de gravação compatível.');
   s.recorder=new MediaRecorder(stream,{mimeType:type,audioBitsPerSecond:64000});s.chunks=[];let bytes=0,seconds=0;
   s.recorder.addEventListener('dataavailable',e=>{if(e.data.size){bytes+=e.data.size;s.chunks.push(e.data);if(bytes>6000000){s.status.textContent='A gravação excedeu 6 MB. Grave um áudio menor.';cancel(s)}}});
   s.recorder.addEventListener('error',()=>{s.status.textContent='Falha na gravação. Confira o microfone.';cancel(s)});
   s.recorder.addEventListener('stop',async()=>{clearTimeout(s.timer);clearInterval(s.clock);s.stream?.getTracks().forEach(t=>t.stop());if(s.cancelled)return;try{const blob=new Blob(s.chunks,{type});s.chunks=[];s.controller=new AbortController();const timeout=setTimeout(()=>s.controller.abort(),60000);let response;try{response=await fetch('/api/transcribe',{method:'POST',headers:{'Content-Type':type},body:blob,signal:s.controller.signal})}finally{clearTimeout(timeout)}const result=await response.json();if(!response.ok)throw Error(result.error||'Não foi possível transcrever.');if(s.cancelled||!s.field.isConnected)return;const combined=[s.field.value.trim(),result.transcript].filter(Boolean).join('\n\n');if(s.field.name==='intake'&&combined.length<=s.field.maxLength){s.field.value=combined;s.field.dispatchEvent(new Event('input',{bubbles:true}));release(s);s.field.dispatchEvent(new CustomEvent('voice:ready',{bubbles:true}));return}s.draft.value=result.transcript;s.review.hidden=false;s.status.textContent='Transcrição pronta. Confira os nomes e os números.';s.draft.focus()}catch(err){if(!s.cancelled)s.status.textContent=err.name==='AbortError'?'A transcrição demorou além do limite. Tente novamente.':err.message}finally{release(s)}});
   s.recorder.start(1000);s.start.disabled=false;s.start.textContent='■ Parar e transcrever';s.status.textContent='Gravando · 0:00 · ao parar, o áudio será enviado ao Deepgram.';s.clock=setInterval(()=>{seconds++;s.status.textContent=`Gravando · ${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')} · máximo 2 min`},1000);s.timer=setTimeout(()=>stop(s),120000);
  }catch(err){s.status.textContent=err.name==='NotAllowedError'?'Permita o microfone no navegador para gravar.':err.name==='NotFoundError'?'Nenhum microfone foi encontrado.':err.message;release(s)}
 }
 window.addEventListener('pagehide',()=>cancel());
 window.addEventListener('beforeunload',e=>{if(active){e.preventDefault();e.returnValue=''}});
 return {mount,cancel};
})();
